import fs from "node:fs";
import path from "node:path";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const rootDir = path.resolve(__dirname, "..");

const BUNDLE_GZ_BASE64 = "";

const TARGETS = [
  ["electron/icons/icon.ico", "electron/icons/icon.ico"],
  ["electron/icons/icon.png", "electron/icons/icon.png"],
  ["public/favicon.png", "public/favicon.png"],
  ["android/app/src/main/res/mipmap-mdpi/ic_launcher.png", "android-mdpi"],
  ["android/app/src/main/res/mipmap-mdpi/ic_launcher_round.png", "android-mdpi"],
  ["android/app/src/main/res/mipmap-hdpi/ic_launcher.png", "android-hdpi"],
  ["android/app/src/main/res/mipmap-hdpi/ic_launcher_round.png", "android-hdpi"],
  ["android/app/src/main/res/mipmap-xhdpi/ic_launcher.png", "android-xhdpi"],
  ["android/app/src/main/res/mipmap-xhdpi/ic_launcher_round.png", "android-xhdpi"],
  ["android/app/src/main/res/mipmap-xxhdpi/ic_launcher.png", "android-xxhdpi"],
  ["android/app/src/main/res/mipmap-xxhdpi/ic_launcher_round.png", "android-xxhdpi"],
  ["android/app/src/main/res/mipmap-xxxhdpi/ic_launcher.png", "android-xxxhdpi"],
  ["android/app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.png", "android-xxxhdpi"],
];

const force = process.argv.includes("--force");
const needsWrite = force || TARGETS.some(([relPath]) => {
  const fullPath = path.join(rootDir, relPath);
  return !fs.existsSync(fullPath) || fs.statSync(fullPath).size === 0;
});

if (needsWrite) {
  const rawJson = zlib.gunzipSync(Buffer.from(BUNDLE_GZ_BASE64, "base64")).toString("utf8");
  const bundle = JSON.parse(rawJson);
  let restored = 0;

  for (const [relPath, key] of TARGETS) {
    const fullPath = path.join(rootDir, relPath);
    if (!force && fs.existsSync(fullPath) && fs.statSync(fullPath).size > 0) {
      continue;
    }
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    fs.writeFileSync(fullPath, Buffer.from(bundle[key], "base64"));
    restored += 1;
  }

  console.log("[ensure-icons] Restored " + restored + " icon asset(s).");
}
